{"script_content": "# Job v8: Discovery-029 H5 -- per-seed intermittency of the super-Rayleigh tail
# Motivation: v7 H3 showed non-monotonic L-dependence of tail ratios exceeding
# Poisson noise -> suspicion that seed-to-seed intermittency (rogue clusters)
# dominates. v8: 32 seeds per L, save PER-SEED ratios so we can quantify the
# intermittent variance directly, not just the pooled mean.
# Config: N=2048, L in {50,100,200}, eps=0.1, frames t in [40,100] every 1.0.
import os, time, json, sys
import numpy as np
import multiprocessing as mp

T0 = time.time()
GUARD = float(os.environ.get('IT_GUARD', '2600'))
CH = int(os.environ.get('IT_CHUNK', '8'))

def say(m):
    print('[H5 ' + str(round(time.time() - T0, 1)) + 's] ' + str(m)); sys.stdout.flush()

RAY = {4: np.exp(-4.0) * (1 + 4), 6: np.exp(-6.0) * (1 + 6),
       8: np.exp(-8.0) * (1 + 8), 10: np.exp(-10.0) * (1 + 10)}
THRS = [4.0, 6.0, 8.0, 10.0]
TSKEY = {4.0: '4', 6.0: '6', 8.0: '8', 10.0: '10'}

def run_real(args):
    (seed, N, L, dt, T, eps) = args
    try:
        dx = L / N
        k = 2.0 * np.pi * np.fft.fftfreq(N, d=dx)
        lin_half = np.exp(-0.5j * (k * k) * dt)
        nsteps = int(round(T / dt))
        rng = np.random.default_rng(seed)
        psi = np.ones(N, dtype=complex)
        psi += eps * (rng.standard_normal(N) + 1j * rng.standard_normal(N)) / np.sqrt(2)
        if abs(psi.real.mean()) > 1e-9:
            psi += (1.0 - psi.real.mean())
        I0 = (psi.real ** 2 + psi.imag ** 2).mean()
        cnt = {'4': 0, '6': 0, '8': 0, '10': 0}
        nsamp = 0
        massdev = 0.0
        Imax_track = 0.0
        tnext = 40.0
        for n in range(1, nsteps + 1):
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            psi *= np.exp(2j * dt * (psi.real ** 2 + psi.imag ** 2))
            psi = np.fft.ifft(lin_half * np.fft.fft(psi))
            t = n * dt
            if t >= tnext - 1e-12 and t <= 100.0 + 1e-12:
                I = psi.real ** 2 + psi.imag ** 2
                m1 = I.mean()
                massdev = max(massdev, abs(m1 - I0))
                Imax_track = max(Imax_track, I.max())
                nsamp += N
                for ts in THRS:
                    cnt[TSKEY[ts]] += int((I >= ts * m1).sum())
                tnext += 1.0
        out = {'ok': True, 'seed': seed, 'nsamp': nsamp, 'cnt': cnt,
               'massdev': massdev, 'Imax': float(Imax_track)}
        return out
    except Exception as e:
        return {'ok': False, 'seed': seed, 'err': repr(e)}

def aggr(res):
    ok = [r for r in res if r.get('ok')]
    if not ok:
        return {'n_ok': 0}
    per_seed = []
    for r in ok:
        ent = {'seed': r['seed'], 'nsamp': r['nsamp'], 'Imax': r['Imax']}
        for ts in THRS:
            kk = TSKEY[ts]
            ent['ratio' + kk] = float((r['cnt'][kk] / r['nsamp']) / RAY[int(ts)])
        per_seed.append(ent)
    pooled = {}
    for ts in THRS:
        kk = TSKEY[ts]
        P = sum(r['cnt'][kk] for r in ok) / sum(r['nsamp'] for r in ok)
        pooled['ratio' + kk] = float(P / RAY[int(ts)])
    rats = {('ratio' + TSKEY[ts]): np.array([e['ratio' + TSKEY[ts]] for e in per_seed])
            for ts in THRS}
    var_stats = {}
    for kk, v in rats.items():
        # Poisson variance expectation for comparison: pooled events ~ n_samp * RAY * ratio
        var_stats[kk] = {'mean': float(v.mean()), 'std': float(v.std(ddof=1)),
                         'min': float(v.min()), 'max': float(v.max()),
                         'cv': float(v.std(ddof=1) / max(v.mean(), 1e-12))}
    return {'n_ok': len(ok), 'pooled': pooled, 'var_stats': var_stats,
            'per_seed': per_seed,
            'massdev': float(np.mean([r['massdev'] for r in ok]))}

def main():
    say('v8 start guard=' + str(GUARD) + ' cpus=' + str(mp.cpu_count()))
    N, dt, T, eps = 2048, 1e-3, 100.0, 0.1
    nreal = int(os.environ.get('IT_NREAL', '32'))
    jobs_all = []
    for L in (50.0, 100.0, 200.0):
        nm = 'H5_L' + str(int(L))
        # disjoint seed block per L
        base = 20000 + int(L) * 100
        jobs_all.append((nm, [(base + i, N, L, dt, T, eps) for i in range(nreal)]))
    pool = None
    try:
        nw = min(8, mp.cpu_count())
        pool = mp.Pool(nw)
        say('pool ' + str(nw))
    except Exception as e:
        say('pool fail ' + repr(e)[:80])
    results = {}
    for nm, jobs in jobs_all:
        res = []
        i = 0
        while i < len(jobs):
            chunk = jobs[i:i + CH]
            got = []
            try:
                if pool is not None:
                    ars = [pool.apply_async(run_real, (j,)) for j in chunk]
                    got = [a.get(timeout=1200) for a in ars]
                else:
                    for j in chunk:
                        if time.time() - T0 > GUARD:
                            break
                        got.append(run_real(j))
            except Exception as e:
                say('chunk fail ' + nm + ': ' + repr(e)[:120])
                try:
                    if pool is not None:
                        pool.terminate(); pool = None
                except Exception:
                    pool = None
                got = []
                for j in chunk:
                    if time.time() - T0 > GUARD:
                        break
                    got.append(run_real(j))
            bad = [g for g in got if not g.get('ok')]
            if bad:
                say(nm + ' bad=' + str(len(bad)) + ' err0=' + bad[0].get('err', '')[:140])
            res.extend([g for g in got if g.get('ok')])
            i += CH
            say(nm + ' chunk: ok=' + str(len(res)) + '/' + str(len(jobs)))
            json.dump({'name': nm, 'n_ok': len(res)}, open('h5_progress.json', 'w'))
            if time.time() - T0 > GUARD - 300:
                say('guard margin low')
                break
        ag = aggr(res)
        results[nm] = {'name': nm, 'n_ok': ag.get('n_ok', 0), 'wall': round(time.time() - T0, 1),
                       'pooled': ag.get('pooled'), 'var_stats': ag.get('var_stats'),
                       'per_seed': ag.get('per_seed'), 'massdev': ag.get('massdev')}
        json.dump(results, open('h5_all_results.json', 'w'))
        say('saved after ' + nm)
        if time.time() - T0 > GUARD - 300:
            break
    say('ALL DONE')
    try:
        if pool is not None:
            pool.close(); pool.join()
    except Exception:
        pass

if __name__ == '__main__':
    main()
", "timeout_seconds": 3200, "title": "H5 v8: Discovery-029 per-seed intermittency of NLS super-Rayleigh tail (32 seeds x 3 box sizes)"}

